from taf.ue.plugin.mtk.commands import ATD
from taf.ue.plugin.mtk.flow.action_verifiable import ActionSequenceVerifiable


class StartVoiceCall(ActionSequenceVerifiable):

    def __init__(self, at_executor=None,
                 call_number=None,
                 verifier=None):
        self._at_executor = at_executor
        self._call_number = call_number
        self._verifier = verifier

    def _generate_command_sequence(self):
        return [ATD(self._at_executor, self._call_number)]

    def verify(self):
        if self._verifier:
            self._verifier.verify()
